using GraphApi.Models.FNZ.Cuentas;namespace GraphApi.Services.FNZ.Cuentas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Cuentas.    /// </summary>    public interface ICuentasService    {        /// <summary>        /// Obtiene la lista de Cuentas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadCuentas>> GetCuentas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Cuentas con filtros opcionales.        /// </summary>        /// <param name="cuentaID">Filtro opcional para CuentaID.</param>        /// <param name="cuenta">Filtro opcional para Cuenta.</param>        /// <param name="tipo">Filtro opcional para Tipo.</param>        /// <param name="saldo">Filtro opcional para Saldo.</param>        /// <param name="responsableUsuarioID">Filtro opcional para ResponsableUsuarioID.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetCuentasDynamic(            int? cuentaID,            string? cuenta,            string? tipo,            decimal? saldo,            int? responsableUsuarioID,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Cuenta.        /// </summary>        /// <param name="objInput">Datos para crear el Cuenta.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCuentas> CreateCuentas(            clCreateCuentas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Cuenta.        /// </summary>        /// <param name="objInput">Datos para actualizar el Cuenta, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCuentas?> UpdateCuentas(            clUpdateCuentas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Cuenta por su ID.        /// </summary>        /// <param name="nCuentasID">ID del Cuenta a eliminar.</param>        Task<bool> DeleteCuentas(int nCuentasID);    }}